<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\PickupLocation;
use Illuminate\Http\{RedirectResponse,Request};
use Illuminate\View\View;
class PickupLocationController extends Controller { public function index():View{return view('admin.pickup-locations.index',['locations'=>PickupLocation::orderBy('sort_order')->get()]);} public function store(Request $r):RedirectResponse{$data=$r->validate(['code'=>'required|alpha_dash|max:40|unique:pickup_locations,code','name'=>'required|string|max:120','province_code'=>'required|string','city_code'=>'required|string','address'=>'required|string','phone'=>'nullable|string|max:30','opening_hours'=>'nullable|string|max:255','instructions'=>'nullable|string','sort_order'=>'required|integer|min:0','is_enabled'=>'nullable|boolean']);$data['is_enabled']=$r->boolean('is_enabled');PickupLocation::create($data);return back()->with('status','محل تحویل ذخیره شد.');} public function update(Request $r,PickupLocation $pickupLocation):RedirectResponse{$data=$r->validate(['name'=>'required|string|max:120','province_code'=>'required|string','city_code'=>'required|string','address'=>'required|string','phone'=>'nullable|string|max:30','opening_hours'=>'nullable|string|max:255','instructions'=>'nullable|string','sort_order'=>'required|integer|min:0','is_enabled'=>'nullable|boolean']);$data['is_enabled']=$r->boolean('is_enabled');$pickupLocation->update($data);return back()->with('status','محل تحویل به‌روزرسانی شد.');} public function destroy(PickupLocation $pickupLocation):RedirectResponse{if(\App\Models\Order::whereJsonContains('shipping_address_snapshot->pickup_location->id',$pickupLocation->id)->exists())abort(422,'محل تحویل استفاده‌شده در تاریخچه سفارش قابل حذف نیست.');$pickupLocation->delete();return back()->with('status','محل تحویل حذف شد.');} }
